// editor/types/shape.js — shape element UI boundary (187 preset variants + create)
// The add menu expands all ECMA-376 presets in a searchable grid; each tiny icon is
// generated by the model evaluator (same geometry as canvas/export). New shapes use
// the preset defaults: no adjustments value, theme primary fill.

import { svgIcon } from "../ui.js";
import {
  PRESET_SHAPES,
  SUPPORTED_SHAPES,
  nextElementId,
  registerType,
  shapeMenuIcon,
} from "../../packages/model/index.js";

/** Cached variant list (187 entries: id / label / group / icon). */
let variants = null;

/** All preset shapes in registry order, with the menu icon rendered on demand. */
function shapeVariants() {
  if (variants) return variants;
  variants = Object.keys(SUPPORTED_SHAPES).map((name) => {
    const preset = PRESET_SHAPES[name] || {};
    const supported = SUPPORTED_SHAPES[name] || {};
    return {
      id: name,
      label: preset.label || supported.label || name,
      group: preset.category || supported.category || "基本",
      icon: shapeMenuIcon(name),
    };
  });
  return variants;
}

/** Default shape model: preset name + theme primary fill (unset adjustments = preset default). */
function createShape(name) {
  const shapeName = SUPPORTED_SHAPES[name] ? name : "rect";
  return {
    elementId: nextElementId("shape"),
    elementType: "shape",
    shapeName,
    bounds: [380, 200, 160, 110],
    adjustments: null,
    fill: { type: "solid", color: "$primary" },
  };
}

registerType({
  type: "shape",
  label: "形状",
  addIcon: svgIcon('<rect x="4" y="4" width="9" height="9" rx="1"/><circle cx="16.5" cy="15.5" r="4.5"/>'),
  addHint: "187 个预设形状，可搜索",
  create: createShape,
  addVariants: shapeVariants,
});
